-- Consolidate multiple permissive RLS policies (2026-10-03).
-- Generated by tools in the operator scratch space; equivalence
-- manifest records each (table, action, role) cell's before/after
-- predicate. All policies on these tables are PERMISSIVE (OR
-- semantics), so disjunctive merging preserves visibility exactly.

-- =============== add_on_purchases ===============
CREATE POLICY "merged_add_on_purchases_select" ON public.add_on_purchases AS PERMISSIVE FOR SELECT TO authenticated
  USING ((((billing_account_id IN ( SELECT billing_accounts.id
   FROM billing_accounts
  WHERE (billing_accounts.user_id = ( SELECT auth.uid() AS uid))))) OR ((EXISTS ( SELECT 1
   FROM billing_accounts ba
  WHERE ((ba.id = add_on_purchases.billing_account_id) AND ((ba.user_id = ( SELECT auth.uid() AS uid)) OR (ba.tenant_id IN ( SELECT tenant_users.tenant_id
           FROM tenant_users
          WHERE (tenant_users.user_id = ( SELECT auth.uid() AS uid)))))))))))
;
CREATE POLICY "merged_add_on_purchases_insert" ON public.add_on_purchases AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((((EXISTS ( SELECT 1
   FROM billing_accounts ba
  WHERE ((ba.id = add_on_purchases.billing_account_id) AND ((ba.user_id = ( SELECT auth.uid() AS uid)) OR (ba.tenant_id IN ( SELECT tenant_users.tenant_id
           FROM tenant_users
          WHERE (tenant_users.user_id = ( SELECT auth.uid() AS uid))))))))) OR ((billing_account_id IN ( SELECT billing_accounts.id
   FROM billing_accounts
  WHERE (billing_accounts.user_id = ( SELECT auth.uid() AS uid)))))))
;
CREATE POLICY "merged_add_on_purchases_update" ON public.add_on_purchases AS PERMISSIVE FOR UPDATE TO authenticated
  USING ((((billing_account_id IN ( SELECT billing_accounts.id
   FROM billing_accounts
  WHERE (billing_accounts.user_id = ( SELECT auth.uid() AS uid))))) OR ((EXISTS ( SELECT 1
   FROM billing_accounts ba
  WHERE ((ba.id = add_on_purchases.billing_account_id) AND ((ba.user_id = ( SELECT auth.uid() AS uid)) OR (ba.tenant_id IN ( SELECT tenant_users.tenant_id
           FROM tenant_users
          WHERE (tenant_users.user_id = ( SELECT auth.uid() AS uid)))))))))))
  WITH CHECK ((((billing_account_id IN ( SELECT billing_accounts.id
   FROM billing_accounts
  WHERE (billing_accounts.user_id = ( SELECT auth.uid() AS uid))))) OR ((EXISTS ( SELECT 1
   FROM billing_accounts ba
  WHERE ((ba.id = add_on_purchases.billing_account_id) AND ((ba.user_id = ( SELECT auth.uid() AS uid)) OR (ba.tenant_id IN ( SELECT tenant_users.tenant_id
           FROM tenant_users
          WHERE (tenant_users.user_id = ( SELECT auth.uid() AS uid)))))))))))
;
CREATE POLICY "merged_add_on_purchases_delete" ON public.add_on_purchases AS PERMISSIVE FOR DELETE TO authenticated
  USING ((((EXISTS ( SELECT 1
   FROM billing_accounts ba
  WHERE ((ba.id = add_on_purchases.billing_account_id) AND ((ba.user_id = ( SELECT auth.uid() AS uid)) OR (ba.tenant_id IN ( SELECT tenant_users.tenant_id
           FROM tenant_users
          WHERE (tenant_users.user_id = ( SELECT auth.uid() AS uid))))))))) OR ((billing_account_id IN ( SELECT billing_accounts.id
   FROM billing_accounts
  WHERE (billing_accounts.user_id = ( SELECT auth.uid() AS uid)))))))
;
DROP POLICY IF EXISTS "add_on_purchases_delete_authenticated" ON public.add_on_purchases;
DROP POLICY IF EXISTS "add_on_purchases_insert_authenticated" ON public.add_on_purchases;
DROP POLICY IF EXISTS "add_on_purchases_isolation" ON public.add_on_purchases;
DROP POLICY IF EXISTS "add_on_purchases_select_authenticated" ON public.add_on_purchases;
DROP POLICY IF EXISTS "add_on_purchases_update_authenticated" ON public.add_on_purchases;
-- =============== add_ons ===============
CREATE POLICY "merged_add_ons_select" ON public.add_ons AS PERMISSIVE FOR SELECT TO public
  USING (((((is_active = true)) AND (pg_has_role(current_user, 'authenticated', 'MEMBER'))) OR (((is_active = true) OR (EXISTS ( SELECT 1
   FROM add_on_purchases
  WHERE ((add_on_purchases.add_on_id = add_ons.id) AND (EXISTS ( SELECT 1
           FROM billing_accounts
          WHERE ((billing_accounts.id = add_on_purchases.billing_account_id) AND (billing_accounts.user_id = current_user_id())))))))))))
;
CREATE POLICY "merged_add_ons_insert" ON public.add_ons AS PERMISSIVE FOR INSERT TO public
  WITH CHECK ((false))
;
CREATE POLICY "merged_add_ons_update" ON public.add_ons AS PERMISSIVE FOR UPDATE TO public
  USING ((false))
  WITH CHECK ((false))
;
CREATE POLICY "merged_add_ons_delete" ON public.add_ons AS PERMISSIVE FOR DELETE TO public
  USING ((false))
;
DROP POLICY IF EXISTS "add_ons_delete_admin" ON public.add_ons;
DROP POLICY IF EXISTS "add_ons_insert_admin" ON public.add_ons;
DROP POLICY IF EXISTS "add_ons_select" ON public.add_ons;
DROP POLICY IF EXISTS "add_ons_select_public" ON public.add_ons;
DROP POLICY IF EXISTS "add_ons_update_admin" ON public.add_ons;
