  USING (((tenant_id = ANY (COALESCE(( SELECT app_private.current_tenant_ids() AS current_tenant_ids), ARRAY[]::uuid[])))))
  WITH CHECK (((tenant_id = ANY (COALESCE(( SELECT app_private.current_tenant_ids() AS current_tenant_ids), ARRAY[]::uuid[])))))
;
