CREATE POLICY "merged_billing_accounts_select" ON public.billing_accounts AS PERMISSIVE FOR SELECT TO public
  USING ((((true) AND (pg_has_role(current_user, 'service_role', 'MEMBER'))) OR ((((user_id = ( SELECT auth.uid() AS uid)) OR (tenant_id IN ( SELECT tu.tenant_id
   FROM tenant_users tu
  WHERE (tu.user_id = ( SELECT auth.uid() AS uid)))) OR (tenant_id = ANY (COALESCE(( SELECT app_private.current_tenant_ids() AS current_tenant_ids), ARRAY[]::uuid[]))))) AND (pg_has_role(current_user, 'authenticated', 'MEMBER'))) OR (((user_id = ( SELECT auth.uid() AS uid))) AND (pg_has_role(current_user, 'authenticated', 'MEMBER')))))
;
CREATE POLICY "merged_billing_accounts_insert" ON public.billing_accounts AS PERMISSIVE FOR INSERT TO public
  WITH CHECK ((((true) AND (pg_has_role(current_user, 'service_role', 'MEMBER'))) OR (((tenant_id = ANY (COALESCE(( SELECT app_private.current_tenant_ids() AS current_tenant_ids), ARRAY[]::uuid[])))) AND (pg_has_role(current_user, 'authenticated', 'MEMBER')))))
;
CREATE POLICY "merged_billing_accounts_update" ON public.billing_accounts AS PERMISSIVE FOR UPDATE TO public
  USING ((((true) AND (pg_has_role(current_user, 'service_role', 'MEMBER'))) OR ((((user_id = ( SELECT auth.uid() AS uid)) OR (tenant_id IN ( SELECT tenant_users.tenant_id
   FROM tenant_users
  WHERE (tenant_users.user_id = ( SELECT auth.uid() AS uid)))) OR (tenant_id = ANY (COALESCE(( SELECT app_private.current_tenant_ids() AS current_tenant_ids), ARRAY[]::uuid[]))))) AND (pg_has_role(current_user, 'authenticated', 'MEMBER'))) OR (((user_id = ( SELECT auth.uid() AS uid))) AND (pg_has_role(current_user, 'authenticated', 'MEMBER')))))
  WITH CHECK ((((true) AND (pg_has_role(current_user, 'service_role', 'MEMBER'))) OR ((((user_id = ( SELECT auth.uid() AS uid)) OR (tenant_id IN ( SELECT tenant_users.tenant_id
   FROM tenant_users
  WHERE (tenant_users.user_id = ( SELECT auth.uid() AS uid)))) OR (tenant_id = ANY (COALESCE(( SELECT app_private.current_tenant_ids() AS current_tenant_ids), ARRAY[]::uuid[]))))) AND (pg_has_role(current_user, 'authenticated', 'MEMBER'))) OR (((user_id = ( SELECT auth.uid() AS uid))) AND (pg_has_role(current_user, 'authenticated', 'MEMBER')))))
;
CREATE POLICY "merged_billing_accounts_delete" ON public.billing_accounts AS PERMISSIVE FOR DELETE TO public
  USING ((((true) AND (pg_has_role(current_user, 'service_role', 'MEMBER'))) OR (((tenant_id = ANY (COALESCE(( SELECT app_private.current_tenant_ids() AS current_tenant_ids), ARRAY[]::uuid[])))) AND (pg_has_role(current_user, 'authenticated', 'MEMBER')))))
;
DROP POLICY IF EXISTS "Service role can manage billing accounts" ON public.billing_accounts;
DROP POLICY IF EXISTS "billing_accounts_select_authenticated_combined" ON public.billing_accounts;
DROP POLICY IF EXISTS "billing_accounts_select_own" ON public.billing_accounts;
DROP POLICY IF EXISTS "billing_accounts_update_authenticated" ON public.billing_accounts;
