-- =============== feature_flags ===============
CREATE POLICY "merged_feature_flags_select" ON public.feature_flags AS PERMISSIVE FOR SELECT TO authenticated
  USING (((((is_global = true) OR (billing_account_id IN ( SELECT billing_accounts.id
   FROM billing_accounts
  WHERE (billing_accounts.user_id = ( SELECT auth.uid() AS uid)))))) OR ((billing_account_id IN ( SELECT ba.id
   FROM billing_accounts ba
  WHERE ((ba.user_id = ( SELECT auth.uid() AS uid)) AND ((ba.status)::text = 'active'::text) AND (ba.deleted_at IS NULL)))))))
;
CREATE POLICY "merged_feature_flags_insert" ON public.feature_flags AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((((billing_account_id IN ( SELECT ba.id
   FROM billing_accounts ba
  WHERE ((ba.user_id = ( SELECT auth.uid() AS uid)) AND ((ba.status)::text = 'active'::text) AND (ba.deleted_at IS NULL)))) AND has_active_subscription(( SELECT auth.uid() AS uid)))))
;
CREATE POLICY "merged_feature_flags_update" ON public.feature_flags AS PERMISSIVE FOR UPDATE TO authenticated
  USING (((billing_account_id IN ( SELECT ba.id
   FROM billing_accounts ba
  WHERE ((ba.user_id = ( SELECT auth.uid() AS uid)) AND ((ba.status)::text = 'active'::text) AND (ba.deleted_at IS NULL))))))
  WITH CHECK (((billing_account_id IN ( SELECT ba.id
   FROM billing_accounts ba
  WHERE ((ba.user_id = ( SELECT auth.uid() AS uid)) AND ((ba.status)::text = 'active'::text) AND (ba.deleted_at IS NULL))))))
;
CREATE POLICY "merged_feature_flags_delete" ON public.feature_flags AS PERMISSIVE FOR DELETE TO authenticated
  USING (((billing_account_id IN ( SELECT ba.id
   FROM billing_accounts ba
  WHERE ((ba.user_id = ( SELECT auth.uid() AS uid)) AND ((ba.status)::text = 'active'::text) AND (ba.deleted_at IS NULL))))))
;
DROP POLICY IF EXISTS "feature_flags_select" ON public.feature_flags;
DROP POLICY IF EXISTS "tenant_isolation_delete" ON public.feature_flags;
DROP POLICY IF EXISTS "tenant_isolation_insert" ON public.feature_flags;
DROP POLICY IF EXISTS "tenant_isolation_select" ON public.feature_flags;
