   FROM billing_accounts ba
  WHERE ((ba.id = receipt_uploads.billing_account_id) AND ((ba.user_id = ( SELECT auth.uid() AS uid)) OR (ba.tenant_id IN ( SELECT tu.tenant_id
           FROM tenant_users tu
          WHERE (tu.user_id = ( SELECT auth.uid() AS uid)))))))) OR (EXISTS ( SELECT 1
   FROM api_keys ak
  WHERE ((ak.id = receipt_uploads.api_key_id) AND (ak.user_id = ( SELECT auth.uid() AS uid))))))))
;
