  USING ((((EXISTS ( SELECT 1
   FROM billing_accounts ba
  WHERE ((ba.id = receipt_uploads.billing_account_id) AND ((ba.user_id = ( SELECT auth.uid() AS uid)) OR (ba.tenant_id IN ( SELECT tenant_users.tenant_id
