-- =============== recon_jobs ===============
CREATE POLICY "merged_recon_jobs_select" ON public.recon_jobs AS PERMISSIVE FOR SELECT TO authenticated
  USING (((((tenant_id IN ( SELECT get_user_tenant_ids() AS get_user_tenant_ids)) OR (tenant_id IN ( SELECT COALESCE(billing_accounts.tenant_id, billing_accounts.id) AS "coalesce"
   FROM billing_accounts
  WHERE (billing_accounts.user_id = ( SELECT auth.uid() AS uid)))))) OR ((tenant_id IN ( SELECT ba.tenant_id
   FROM billing_accounts ba
  WHERE ((ba.user_id = ( SELECT auth.uid() AS uid)) AND ((ba.status)::text = 'active'::text) AND (ba.deleted_at IS NULL)))))))
;
CREATE POLICY "merged_recon_jobs_insert" ON public.recon_jobs AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((((tenant_id IN ( SELECT get_user_tenant_ids() AS get_user_tenant_ids)) OR (tenant_id IN ( SELECT COALESCE(billing_accounts.tenant_id, billing_accounts.id) AS "coalesce"
   FROM billing_accounts
  WHERE (billing_accounts.user_id = ( SELECT auth.uid() AS uid)))))) OR (((tenant_id IN ( SELECT ba.tenant_id
   FROM billing_accounts ba
  WHERE ((ba.user_id = ( SELECT auth.uid() AS uid)) AND ((ba.status)::text = 'active'::text) AND (ba.deleted_at IS NULL)))) AND has_active_subscription(( SELECT auth.uid() AS uid))))))
;
CREATE POLICY "merged_recon_jobs_update" ON public.recon_jobs AS PERMISSIVE FOR UPDATE TO authenticated
