  WITH CHECK ((((tenant_id = ANY (COALESCE(( SELECT app_private.current_tenant_ids() AS current_tenant_ids), ARRAY[]::uuid[])))) OR ((tenant_id IN ( SELECT get_user_tenant_ids() AS get_user_tenant_ids)))))
;
CREATE POLICY "merged_webhooks_delete" ON public.webhooks AS PERMISSIVE FOR DELETE TO authenticated
  USING ((((tenant_id = ANY (COALESCE(( SELECT app_private.current_tenant_ids() AS current_tenant_ids), ARRAY[]::uuid[])))) OR ((tenant_id IN ( SELECT get_user_tenant_ids() AS get_user_tenant_ids)))))
;
DROP POLICY IF EXISTS "tenant_delete" ON public.webhooks;
DROP POLICY IF EXISTS "tenant_insert" ON public.webhooks;
DROP POLICY IF EXISTS "tenant_select" ON public.webhooks;
DROP POLICY IF EXISTS "tenant_update" ON public.webhooks;
DROP POLICY IF EXISTS "webhooks_delete" ON public.webhooks;
DROP POLICY IF EXISTS "webhooks_insert" ON public.webhooks;
DROP POLICY IF EXISTS "webhooks_select" ON public.webhooks;
DROP POLICY IF EXISTS "webhooks_update" ON public.webhooks;
